saasField('quantity','Nombre d’unités facturables');
saasField('unit_price','Prix HT par unité et par période');
saasField('options','Total des options HT par période');
saasField('setup','Installation HT (une fois)');
saasField('training','Formation HT (une fois)');
const saasActions=document.createElement('div');saasActions.className='wide';const saasSubmit=document.createElement('button');saasSubmit.textContent='Simuler les revenus';const saasReset=document.createElement('button');saasReset.type='reset';saasReset.textContent='Effacer la simulation';saasActions.append(saasSubmit,document.createTextNode(' '),saasReset);saasForm.append(saasActions);
const saasNotice=document.createElement('p');saasNotice.id='saas-notice';saasNotice.setAttribute('role','status');const saasResults=document.createElement('div');saasResults.id='saas-results';saasResults.className='counts';saasResults.setAttribute('aria-live','polite');
saasSection.append(saasHeading,saasIntro,saasForm,saasNotice,saasResults);byId('catalogue-interne').after(saasSection);const saasLink=document.createElement('a');saasLink.href='#saas-simulation';saasLink.textContent='Simulation SaaS';document.querySelector('.workflow-nav').append(saasLink);
let saasEpoch=0;
function clearSaas(){saasEpoch++;saasResults.replaceChildren();saasNotice.textContent='';saasSubmit.disabled=false}
saasForm.addEventListener('input',clearSaas);saasForm.addEventListener('reset',clearSaas);
saasForm.onsubmit=async e=>{e.preventDefault();clearSaas();if(!token)return;const current=saasEpoch,session=token;const data=Object.fromEntries(new FormData(saasForm));data.quantity=Number(data.quantity);saasSubmit.disabled=true;try{const result=await api('crm/saas-simulation',{method:'POST',body:JSON.stringify(data)});if(current!==saasEpoch||session!==token)return;for(const [key,label] of Object.entries({recurring:'Montant par période',mrr:'MRR estimé',arr:'ARR estimé',one_off:'Frais ponctuels',first_year:'Total première année HT'})){const card=document.createElement('div');card.className='count';const amount=document.createElement('strong');amount.textContent=result[key]+' '+result.currency;card.append(amount,document.createTextNode(label));saasResults.append(card)}saasNotice.textContent=result.product_name+' — simulation indicative, sans engagement. MRR arrondi à la précision de la devise.'}catch(error){if(current===saasEpoch&&session===token)saasNotice.textContent=error.message}finally{if(current===saasEpoch&&session===token)saasSubmit.disabled=false}};

const scForm=byId('sc-form'),scResults=byId('sc-results'),scNotice=byId('sc-notice');
