const offerRows=document.createElement('div');offerRows.id='saas-offer-rows';const offerPager=document.createElement('div');offerPager.className='toolbar';const offerPrev=document.createElement('button'),offerNext=document.createElement('button'),offerPageLabel=document.createElement('span');offerPrev.textContent='Précédent';offerNext.textContent='Suivant';offerPager.append(offerPrev,offerPageLabel,offerNext);
offerSection.append(offerHeading,offerIntro,offerForm,offerNotice,offerRows,offerPager);saasSection.after(offerSection);const offerLink=document.createElement('a');offerLink.href='#saas-offers';offerLink.textContent='Offres SaaS';document.querySelector('.workflow-nav').append(offerLink);
let offerPage=1,offerEpoch=0,offerLookupEpoch=0;
const subscriptionSection=document.createElement('section');subscriptionSection.id='saas-subscriptions';subscriptionSection.className=offerSection.className;
const subscriptionHeading=document.createElement('h2');subscriptionHeading.textContent='Abonnements SaaS';
