const subscriptionPager=document.createElement('div');subscriptionPager.className='toolbar';const subscriptionPrev=document.createElement('button'),subscriptionNext=document.createElement('button'),subscriptionPageLabel=document.createElement('span');subscriptionPrev.textContent='Précédent';subscriptionNext.textContent='Suivant';subscriptionPager.append(subscriptionPrev,subscriptionPageLabel,subscriptionNext);
const subscriptionMetrics=document.createElement('div');subscriptionMetrics.id='saas-subscription-metrics';const subscriptionFilter=document.createElement('select');subscriptionFilter.setAttribute('aria-label','État des abonnements SaaS');for(const [value,label] of Object.entries({'':'Tous les états',PLANIFIE:'Planifiés',ACTIF:'Actifs',EXPIRE:'Expirés',ECHEANCE_30J:'Échéance sous 30 jours'}))subscriptionFilter.append(option(value,label));
subscriptionSection.append(subscriptionHeading,subscriptionIntro,subscriptionMetrics,subscriptionSearch,subscriptionFilter,subscriptionNotice,subscriptionRows,subscriptionPager);offerSection.after(subscriptionSection);const subscriptionLink=document.createElement('a');subscriptionLink.href='#saas-subscriptions';subscriptionLink.textContent='Abonnements SaaS';document.querySelector('.workflow-nav').append(subscriptionLink);
let subscriptionPage=1,subscriptionEpoch=0,subscriptionTimer;
function renderSubscriptionMetrics(metrics){subscriptionMetrics.replaceChildren();const heading=document.createElement('p');heading.textContent='Situation globale au '+metrics.as_of+' : '+metrics.counts.ACTIF+' actifs · '+metrics.counts.PLANIFIE+' planifiés · '+metrics.counts.EXPIRE+' expirés · '+metrics.counts.ECHEANCE_30J+' échéance(s) sous 30 jours.';subscriptionMetrics.append(heading);for(const group of metrics.groups){const p=document.createElement('p');p.textContent=group.product_name+' · '+group.active+' actif(s) · MRR estimé '+group.mrr+' '+group.currency+' · ARR estimé '+group.arr+' '+group.currency;subscriptionMetrics.append(p)}for(const group of metrics.billing_groups){const p=document.createElement('p');p.textContent=group.product_name+' · Facturé TTC '+group.invoiced+' · encaissé '+group.received+' · restant '+group.outstanding+' · en retard '+group.overdue+' '+group.currency;subscriptionMetrics.append(p)}}
subscriptionFilter.onchange=()=>{clearTimeout(subscriptionTimer);subscriptionPage=1;if(token)loadSubscriptions()};
async function loadSubscriptions(){const current=++subscriptionEpoch,session=token;try{const d=await api('crm/saas-subscriptions?'+new URLSearchParams({page:subscriptionPage,q:subscriptionSearch.value,status:subscriptionFilter.value}));if(!token||token!==session||current!==subscriptionEpoch)return;renderSubscriptionMetrics(d.metrics);subscriptionRows.replaceChildren();for(const item of d.items){const box=document.createElement('details'),heading=document.createElement('summary'),info=document.createElement('p');heading.textContent=item.company+' — '+item.title+' · '+item.status;info.textContent=item.estimate.product_name+' · '+item.starts_on+' → '+item.ends_on+' (exclue) · Référence : '+item.reference+' · MRR estimé : '+item.estimate.mrr+' '+item.estimate.currency+' · ARR estimé : '+item.estimate.arr+' '+item.estimate.currency;const context=document.createElement('p');context.textContent='Identifiant : '+item.id+' · '+(item.predecessor_id?'Renouvellement de '+item.predecessor_id:'Abonnement initial')+' · '+(item.successor_id?'Renouvellement enregistré':item.status==='ACTIF'&&item.days_to_end<=30?'Échéance dans '+item.days_to_end+' jour(s)':'');box.append(heading,info,context);subscriptionLifecycle(item,box);subscriptionBilling(item,box);subscriptionRows.append(box)}if(!d.items.length)subscriptionRows.textContent='Aucun abonnement.';subscriptionPageLabel.textContent='Page '+subscriptionPage+' · '+d.total+' abonnement(s)';subscriptionPrev.disabled=subscriptionPage===1;subscriptionNext.disabled=subscriptionPage*10>=d.total}catch(e){if(token===session&&current===subscriptionEpoch)subscriptionNotice.textContent=e.message}}
function subscriptionLifecycle(item,box){const lifecycle=item.lifecycle,info=document.createElement('p');info.textContent='Cycle de vie : '+lifecycle.state;box.append(info);const history=document.createElement('details'),summary=document.createElement('summary');summary.textContent='Historique des décisions ('+lifecycle.events.length+')';history.append(summary);for(const event of lifecycle.events){const p=document.createElement('p');p.textContent=event.action+' · effet '+event.effective_on+' · '+event.actor+' · '+event.evidence;history.append(p)}box.append(history);if(!lifecycle.actions.length)return;const form=document.createElement('form');form.className='editor';const action=document.createElement('select');action.setAttribute('aria-label','Décision abonnement');for(const a of lifecycle.actions)action.append(option(a,a));const dateLabel=document.createElement('label'),effective=document.createElement('input');effective.type='date';effective.required=true;dateLabel.textContent='Date d’effet';dateLabel.append(effective);const evidenceLabel=document.createElement('label'),evidence=document.createElement('textarea');evidence.required=true;evidence.maxLength=1000;evidenceLabel.textContent='Motif et référence de la décision';evidenceLabel.append(evidence);const note=document.createElement('p');note.textContent='Suspension et réactivation internes sans effet financier. Résiliation à une limite de période, justificatif contractuel obligatoire.';const save=document.createElement('button');save.textContent='Enregistrer la décision';form.append(action,dateLabel,evidenceLabel,note,save);box.append(form);form.onsubmit=async e=>{e.preventDefault();const session=token;if(!session||!confirm('Confirmer cette décision documentée ?'))return;save.disabled=true;try{await api('crm/saas-subscriptions/'+encodeURIComponent(item.id)+'/decision',{method:'POST',body:JSON.stringify({version:lifecycle.version,action:action.value,effective_on:effective.value,evidence:evidence.value})});if(token===session){await Promise.all([loadSubscriptions(),loadCommercial()]);subscriptionNotice.textContent='Décision enregistrée.'}}catch(error){if(token===session&&box.isConnected){info.textContent=error.message;save.disabled=false}}}}
function subscriptionBilling(item,box){const button=document.createElement('button'),panel=document.createElement('div');button.type='button';button.textContent='Voir l’échéancier de facturation';panel.hidden=true;box.append(button,panel);let page=1,epoch=0;async function load(){const session=token,current=++epoch;try{const path='crm/saas-subscriptions/'+encodeURIComponent(item.id)+'/billing';const d=await api(path+'?page='+page);if(!token||token!==session||current!==epoch||!box.isConnected)return;panel.replaceChildren();const intro=document.createElement('p');intro.textContent=d.prepared_count+'/'+d.total+' échéances préparées · montants HT contractuels, rapprochement des factures externes.';panel.append(intro);for(const period of d.items){const row=document.createElement('div'),label=document.createElement('p');label.textContent=period.period_start+' → '+period.period_end+' (exclue) · '+period.total_ht+' '+period.currency+' HT · '+(period.prepared?'Préparée':'À préparer');row.append(label);if(d.can_prepare&&!period.prepared){const save=document.createElement('button');save.type='button';save.textContent='Préparer cette échéance';save.onclick=async()=>{if(!confirm('Enregistrer cette préparation interne, sans émission de facture ?'))return;save.disabled=true;try{await api(path,{method:'POST',body:JSON.stringify({period_start:period.period_start})});if(token===session)await load()}catch(e){if(token===session&&box.isConnected){label.textContent=e.message;save.disabled=false}}};row.append(save)}if(period.prepared)invoiceControls(row,period,d.can_prepare,path,load);panel.append(row)}const prev=document.createElement('button'),next=document.createElement('button');prev.textContent='Précédent';next.textContent='Suivant';prev.disabled=page===1;next.disabled=page*10>=d.total;prev.onclick=()=>{page--;load()};next.onclick=()=>{page++;load()};panel.append(prev,next)}catch(e){if(token===session&&current===epoch&&box.isConnected)panel.textContent=e.message}}button.onclick=()=>{panel.hidden=!panel.hidden;if(!panel.hidden)load();else epoch++}}
function invoiceControls(row,period,allowed,path,reload){const invoice=period.invoice;const info=document.createElement('p');info.textContent=invoice?'Facture '+invoice.reference+' · '+invoice.status+' · TTC '+invoice.total+' · encaissé '+invoice.paid+' · solde '+invoice.balance+' '+period.currency:'Aucune facture rapprochée.';row.append(info);if(!allowed||(invoice&&invoice.status==='REGLEE'))return;const form=document.createElement('form');form.className='editor';const action=invoice?'receipt':'invoice';function field(name,label,type){const wrap=document.createElement('label'),input=document.createElement('input');wrap.textContent=label;input.type=type;input.name=name;input.required=true;wrap.append(input);form.append(wrap);return input}field('reference',invoice?'Référence du règlement réel':'Référence de la facture émise','text').maxLength=120;if(invoice){field('paid_on','Date réelle du règlement','date');field('amount','Montant reçu','text')}else{field('issued_on','Date d’émission réelle','date');field('due_on','Date limite de règlement','date');field('tax','Montant de taxe figurant sur la facture (0 si aucune)','text')}const save=document.createElement('button');save.textContent=invoice?'Enregistrer le règlement':'Rapprocher la facture';form.append(save);row.append(form);form.onsubmit=async e=>{e.preventDefault();const session=token;if(!session||!confirm('Confirmer les informations du document réel ?'))return;save.disabled=true;try{await api(path,{method:'POST',body:JSON.stringify({...Object.fromEntries(new FormData(form)),action,period_start:period.period_start})});if(token===session)await reload()}catch(error){if(token===session){info.textContent=error.message;save.disabled=false}}}}
subscriptionSearch.oninput=()=>{clearTimeout(subscriptionTimer);subscriptionEpoch++;subscriptionPage=1;subscriptionPrev.disabled=subscriptionNext.disabled=true;subscriptionTimer=setTimeout(()=>{if(token)loadSubscriptions()},250)};
subscriptionPrev.onclick=()=>{if(subscriptionPage>1){subscriptionPage--;loadSubscriptions()}};subscriptionNext.onclick=()=>{if(!subscriptionNext.disabled){subscriptionPage++;loadSubscriptions()}};
function subscriptionForm(item,details){if(item.subscription_id){const p=document.createElement('p');p.textContent='Abonnement déjà enregistré.';details.append(p);return}if(!item.can_register_subscription)return;const form=document.createElement('form');form.className='editor';function field(name,label,type){const wrap=document.createElement('label'),input=document.createElement('input');wrap.textContent=label;input.name=name;input.type=type;input.required=true;wrap.append(input);form.append(wrap);return input}field('starts_on','Début contractuel','date');field('ends_on','Fin contractuelle (exclue)','date');field('reference','Référence du contrat signé','text').maxLength=500;const previous=field('predecessor_id','Identifiant de l’abonnement précédent (renouvellement facultatif)','text');previous.required=false;previous.maxLength=36;const save=document.createElement('button');save.textContent='Enregistrer l’abonnement';form.append(save);details.append(form);form.onsubmit=async e=>{e.preventDefault();const session=token;if(!token||!confirm('Confirmez-vous disposer d’un contrat signé correspondant à cette offre ?'))return;save.disabled=true;try{await api('crm/saas-subscriptions',{method:'POST',body:JSON.stringify({...Object.fromEntries(new FormData(form)),offer_id:item.id})});if(token===session){subscriptionPage=1;await Promise.all([loadSaasOffers(),loadSubscriptions()]);offerNotice.textContent='Abonnement enregistré dans le registre interne.'}}catch(error){if(token===session)offerNotice.textContent=error.message}finally{save.disabled=false}}}
