const originalLogout=byId('logout').onclick;byId('logout').onclick=()=>{clearTimeout(subscriptionTimer);subscriptionEpoch++;subscriptionSearch.value='';subscriptionFilter.value='';subscriptionMetrics.replaceChildren();subscriptionRows.replaceChildren();subscriptionNotice.textContent='';subscriptionPageLabel.textContent='';originalLogout()};
function clearOfferWorkspace(){offerEpoch++;offerLookupEpoch++;offerForm.reset();offerOpportunity.replaceChildren(option('','Sélectionner'));offerRows.replaceChildren();offerNotice.textContent='';offerPageLabel.textContent='';offerSave.disabled=false}
offerFind.onclick=async()=>{const current=++offerLookupEpoch,session=token;try{const d=await api('crm?'+new URLSearchParams({q:offerSearch.value,page_size:25}));if(!token||token!==session||current!==offerLookupEpoch)return;offerOpportunity.replaceChildren(option('','Sélectionner'));for(const item of d.items)offerOpportunity.append(option(item.id,item.company+' — '+item.title));offerNotice.textContent=d.total>25?'Précisez la recherche (25 premiers résultats).':d.total+' opportunité(s).'}catch(e){if(token===session&&current===offerLookupEpoch)offerNotice.textContent=e.message}};
